  `date` date NOT NULL,
  `followers` bigint NOT NULL DEFAULT '0',
  `following` bigint DEFAULT '0',
  `media_count` bigint DEFAULT '0',
  `reach` bigint DEFAULT '0',
  `impressions` bigint DEFAULT '0',
  `likes` bigint DEFAULT '0',
  `comments` bigint DEFAULT '0',
  `saves` bigint DEFAULT '0',
  `shares` bigint DEFAULT '0',
  `engagement` bigint DEFAULT '0',
  `profile_visits` bigint DEFAULT '0',
  `website_clicks` bigint DEFAULT '0',
  `engagement_rate` decimal(8,4) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_account_date` (`connected_account_id`,`date`),
  KEY `connected_account_metrics_connected_account_id_date_index` (`connected_account_id`,`date`),
  CONSTRAINT `connected_account_metrics_connected_account_id_foreign` FOREIGN KEY (`connected_account_id`) REFERENCES `connected_accounts` (`id`) ON DELETE CASCADE
