mily: \'Sora\', sans-serif !important;\\\\n}\\\\n\\\\n\\\\/* Specific element overrides *\\\\/\\\\n.fi-sidebar-navigation-item-label,\\\\n.fi-sidebar-group-label,\\\\n.fi-topbar-item-label,\\\\n.fi-page-heading,\\\\n.fi-page-description,\\\\n.fi-table-header-cell-text,\\\\n.fi-table-cell-text,\\\\n.fi-form-section-heading,\\\\n.fi-form-field-label,\\\\n.fi-input-label,\\\\n.fi-select-option-label,\\\\n.fi-relation-manager-header,\\\\n.fi-relation-manager-row,\\\\n.fi-infolist-entry-label,\\\\n.fi-infolist-entry-value {\\\\n    font-family: \'Sora\', sans-serif !important;\\\\n}\\\\n\\\\n.tabular-nums {\\\\n    font-variant-numeric: tabular-nums;\\\\n}\\\\n\\\\n\\\\/* Scroll *\\\\/\\\\n.custom-scroll::-webkit-scrollbar {\\\\n    width: 6px;\\\\n}\\\\n.custom-scroll::-webkit-scrollbar-thumb {\\\\n    background-color: #d1d5db;\\\\n    border-radius: 9999px;\\\\n}\\\\n.custom-scroll::-webkit-scrollbar-track {\\\\n    background: transparent;\\\\n}\\\\n\\\\n\\\\/* Task Today Widget Improvements *\\\\/\\\\n.task-today-card {\\\\n    @apply transition-all duration-300 ease-in-out;\\\\n}\\\\n\\\\n.task-today-card:hover {\\\\n    @apply shadow-xl -translate-y-1;\\\\n}\\\\n\\\\n\\\\/* Smooth animations *\\\\/\\\\n@keyframes fadeIn {\\\\n    from {\\\\n        opacity: 0;\\\\n        transform: translateY(10px);\\\\n    }\\\\n    to {\\\\n        opacity: 1;\\\\n        transform: translateY(0);\\\\n    }\\\\n}\\\\n\\\\n.task-today-card {\\\\n    animation: fadeIn 0.3s ease-out;\\\\n}\\\\n\\\\n\\\\/* Empty state animation *\\\\/\\\\n.empty-state-icon {\\\\n    animation: float 3s ease-in-out infinite;\\\\n}\\\\n\\\\n@keyframes float {\\\\n    0%, 100% {\\\\n        transform: translateY(0);\\\\n    }\\\\n    50% {\\\\n        transform: translateY(-10px);\\\\n    }\\\\n}\\\\n\\\\n\\\\/* Status badge improvements *\\\\/\\\\n.status-badge {\\\\n    @apply px-2.5 py-1 rounded-full text-xs font-semibold transition-all;\\\\n}\\\\n\\\\n.status-badge:hover {\\\\n    @apply transform scale-105;\\\\n}\\\\n\\\\n\\\\/* Priority badge pulse animation *\\\\/\\\\n.priority-urgent {\\\\n    animation: pulse-urgent 2s ease-in-out infinite;\\\\n}\\\\n\\\\n@keyframes pulse-urgent {\\\\n    0%, 100% {\\\\n        opacity: 1;\\\\n        box-shadow: 0 0 0 0 rgba(239, 68, 68, 0.7);\\\\n    }\\\\n    50% {\\\\n        opacity: 0.9;\\\\n        box-shadow: 0 0 0 8px rgba(239, 68, 68, 0);\\\\n    }\\\\n}\\\\n\\\\n\\\\/* Deadline warning animation *\\\\/\\\\n.deadline-today {\\\\n    animation: shake 0.5s ease-in-out;\\\\n}\\\\n\\\\n@keyframes shake {\\\\n    0%, 100% { transform: translateX(0); }\\\\n    25% { transform: translateX(-3px); }\\\\n    75% { transform: translateX(3px); }\\\\n}\\\\n\\\\n\\\\/* Avatar stack hover effect *\\\\/\\\\n.avatar-stack:hover .avatar-item {\\\\n    @apply transform -translate-y-1;\\\\n}\\\\n\\\\n.avatar-item {\\\\n    @apply transition-transform duration-200;\\\\n}\\\\n\\\\n\\\\/* Gradient backgrounds *\\\\/\\\\n.gradient-primary {\\\\n    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);\\\\n}\\\\n\\\\n.gradient-success {\\\\n    background: linear-gradient(135deg, #f093fb 0%, #f5576c 100%);\\\\n}\\\\n\\\\n\\\\/* Card hover effects *\\\\/\\\\n.task-card-hover {\\\\n    @apply relative overflow-hidden;\\\\n}\\\\n\\\\n.task-card-hover::before {\\\\n    content: \'\';\\\\n    @apply absolute inset-0 bg-gradient-to-r from-primary-500\\\\/0 via-primary-500\\\\/10 to-primary-500\\\\/0 -translate-x-full;\\\\n    transition: transform 0.5s;\\\\n}\\\\n\\\\n.task-card-hover:hover::before {\\\\n    @apply translate-x-full;\\\\n}\\\\n\\\\n\\\\/* Line clamp for long text *\\\\/\\\\n.line-clamp-1 {\\\\n    display: -webkit-box;\\\\n    -webkit-line-clamp: 1;\\\\n    -webkit-box-orient: vertical;\\\\n    overflow: hidden;\\\\n}\\\\n\\\\n.line-clamp-2 {\\\\n    display: -webkit-box;\\\\n    -webkit-line-clamp: 2;\\\\n    -webkit-box-orient: vertical;\\\\n    overflow: hidden;\\\\n}\\\\n\\\\n\\\\/* Dark mode improvements *\\\\/\\\\n.dark .task-card {\\\\n    @apply bg-gray-900\\\\/50 border-gray-800;\\\\n}\\\\n\\\\n.dark .task-card:hover {\\\\n    @apply bg-gray-800 border-primary-700;\\\\n}\\\\n\\\\n\\\\/* Responsive adjustments *\\\\/\\\\n@media (max-width: 768px) {\\\\n    .task-card-content {\\\\n        @apply text-sm;\\\\n    }\\\\n    \\\\n    .task-card-icon {\\\\n        @apply w-10 h-10;\\\\n    }\\\\n    \\\\n    .task-card-icon svg {\\\\n        @apply w-5 h-5;\\\\n    }\\\\n}\\\\n\\\\n\\\\/* Loading skeleton *\\\\/\\\\n.skeleton {\\\\n    @apply animate-pulse bg-gray-200 dark:bg-gray-700 rounded;\\\\n}\\\\n\\\\n\\\\/* Custom scrollbar for task list *\\\\/\\\\n.task-list-container {\\\\n    max-height: 600px;\\\\n    overflow-y: auto;\\\\n}\\\\n\\\\n.task-list-container::-webkit-scrollbar {\\\\n    width: 6px;\\\\n}\\\\n\\\\n.task-list-container::-webkit-scrollbar-track {\\\\n    @apply bg-gray-100 dark:bg-gray-800 rounded-full;\\\\n}\\\\n\\\\n.task-list-container::-webkit-scrollbar-thumb {\\\\n    @apply bg-gray-300 dark:bg-gray-600 rounded-full;\\\\n}\\\\n\\\\n.task-list-container::-webkit-scrollbar-thumb:hover {\\\\n    @apply bg-gray-400 dark:bg-gray-500;\\\\n}\\\\n\\\\n\\\\/* ============================================\\\\n   FORCE CALENDAR + TASK SIDEBY-SIDE LAYOUT\\\\n   ============================================ *\\\\/\\\\n\\\\n\\\\/* Target widget containers *\\\\/\\\\n.fi-wi-calendar {\\\\n    grid-column: span 3 \\\\/ span 3 !important;\\\\n    width: 75% !important;\\\\n    float: left !important;\\\\n    min-height: 650px !important;\\\\n}\\\\n\\\\n.fi-wi-task-today-widget {\\\\n    grid-column: span 1 \\\\/ span 1 !important;\\\\n    width: 25% !important;\\\\n    float: left !important;\\\\n    min-height: 650px !important;\\\\n}\\\\n\\\\n\\\\/* Clear float after widgets *\\\\/\\\\n.fi-wi-calendar + .fi-wi-task-today-widget::after {\\\\n    content: \'\';\\\\n    display: table;\\\\n    clear: both;\\\\n}\\\\n\\\\n\\\\/* Make calendar taller *\\\\/\\\\n.fi-wi